// Writes ../web/demo.js: the firmware's `hello` and `desc` answers, for the page's
// demo mode (no module). Generated by `make web`; ../tests checks it is current.
#include <stdio.h>
#include <string.h>

#include "ms_proto.h"

static bool in_desc;

static void js_string(const char *s) {
    putchar('"');
    for (; *s; s++) {
        if (*s == '"' || *s == '\\') putchar('\\');
        putchar(*s);
    }
    putchar('"');
}

static void out(void *ctx, const char *line) {
    if (in_desc) {
        printf("    ");
        js_string(line);
        printf(",\n");
    } else {
        js_string(line);
    }
}
static void apply(void *ctx, const float values[MS_P_COUNT]) {}
static void meters(void *ctx, ms_meters_t *m) {}
static void status(void *ctx, ms_status_t *st) {
    st->fs = 44100;
    st->block = 16;
    st->io_ms = 2.3f;
}

int main(void) {
    ms_host_t host = {.out = out, .apply = apply, .meters = meters, .status = status};
    static ms_proto_t pr;
    ms_proto_init(&pr, &host);
    char hello[] = "hello", desc[] = "desc";
    printf("// Generated by `make web` in ../tools (gen_web_demo.c). Do not edit.\n");
    printf("const MASTER_DEMO = {\n  hello: ");
    ms_proto_line(&pr, hello);
    printf(",\n  desc: [\n");
    in_desc = true;
    ms_proto_line(&pr, desc);
    printf("  ],\n  meters: ");
    char names[256];
    snprintf(names, sizeof(names), "%s", ms_meter_names);
    js_string(names);
    printf(".split(\" \"),\n};\n");
    return 0;
}
